-- Datos ficticios del ejemplo .NET, adaptados para los reportes de Java.
-- Ejecutar SOLO en la base de práctica después de la extensión TG23.
USE SIGH_GR06;
SET NAMES utf8mb4;
START TRANSACTION;
SET @usuario = (SELECT XEUSU_CODIGO FROM XEUSU_USUAR WHERE XEUSU_CODIGO='MONSTER' LIMIT 1);
INSERT IGNORE INTO PACIENTE (PACIENTE_IDENTIFICADOR_HOSPITALARIO,PACIENTE_NOMBRES,PACIENTE_APELLIDOS,XEUSU_CODIGO) VALUES
('TG23-PAC-01','Camila','Paciente Demo',@usuario),('TG23-PAC-02','Pedro','Paciente Demo',@usuario);
SET @p1=(SELECT PACIENTE_ID_PACIENTE FROM PACIENTE WHERE PACIENTE_IDENTIFICADOR_HOSPITALARIO='TG23-PAC-01');
SET @p2=(SELECT PACIENTE_ID_PACIENTE FROM PACIENTE WHERE PACIENTE_IDENTIFICADOR_HOSPITALARIO='TG23-PAC-02');
INSERT IGNORE INTO PROFESIONAL (PROFESIONAL_NUMERO_REGISTRO,PROFESIONAL_NOMBRES,PROFESIONAL_APELLIDOS,PROFESIONAL_TIPO_PROFESIONAL) VALUES ('TG23-PRO-01','Alejandra','Taller Uno','Medicina general');
SET @prof=(SELECT PROFESIONAL_ID_PROFESIONAL FROM PROFESIONAL WHERE PROFESIONAL_NUMERO_REGISTRO='TG23-PRO-01');
INSERT IGNORE INTO ESPECIALIDAD (ESPECIALIDAD_NOMBRE,ESPECIALIDAD_DESCRIPCION) VALUES ('Medicina general','Consulta de demostración');
SET @esp=(SELECT ESPECIALIDAD_ID_ESPECIALIDAD FROM ESPECIALIDAD WHERE ESPECIALIDAD_NOMBRE='Medicina general');
INSERT IGNORE INTO CONSULTORIO (CONSULTORIO_CODIGO,CONSULTORIO_UBICACION) VALUES ('TG23-CON-01','Planta baja');
SET @con=(SELECT CONSULTORIO_ID_CONSULTORIO FROM CONSULTORIO WHERE CONSULTORIO_CODIGO='TG23-CON-01');
INSERT INTO AGENDA_MEDICA (PROFESIONAL_ID_PROFESIONAL,ESPECIALIDAD_ID_ESPECIALIDAD,CONSULTORIO_ID_CONSULTORIO,AGENDA_MEDICA_INICIO,AGENDA_MEDICA_FIN,AGENDA_MEDICA_DURACION_MINUTOS,AGENDA_MEDICA_ESTADO)
SELECT @prof,@esp,@con,'2026-11-26 08:00:00','2026-11-26 16:00:00',30,'DISPONIBLE' FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM AGENDA_MEDICA WHERE PROFESIONAL_ID_PROFESIONAL=@prof AND CONSULTORIO_ID_CONSULTORIO=@con AND AGENDA_MEDICA_INICIO='2026-11-26 08:00:00');
SET @agenda=(SELECT MIN(AGENDA_MEDICA_ID_AGENDA) FROM AGENDA_MEDICA WHERE PROFESIONAL_ID_PROFESIONAL=@prof AND CONSULTORIO_ID_CONSULTORIO=@con AND AGENDA_MEDICA_INICIO='2026-11-26 08:00:00');
INSERT INTO CITA (PACIENTE_ID_PACIENTE,AGENDA_MEDICA_ID_AGENDA,XEUSU_CODIGO,CITA_FECHA_HORA,CITA_MOTIVO,CITA_ESTADO)
SELECT @p1,@agenda,@usuario,'2026-11-26 09:00:00','Consulta de demostración','ATENDIDA' FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM CITA WHERE AGENDA_MEDICA_ID_AGENDA=@agenda AND PACIENTE_ID_PACIENTE=@p1 AND CITA_FECHA_HORA='2026-11-26 09:00:00');
INSERT INTO CITA (PACIENTE_ID_PACIENTE,AGENDA_MEDICA_ID_AGENDA,XEUSU_CODIGO,CITA_FECHA_HORA,CITA_MOTIVO,CITA_ESTADO)
SELECT @p2,@agenda,@usuario,'2026-11-26 10:00:00','Control de demostración','PROGRAMADA' FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM CITA WHERE AGENDA_MEDICA_ID_AGENDA=@agenda AND PACIENTE_ID_PACIENTE=@p2 AND CITA_FECHA_HORA='2026-11-26 10:00:00');
INSERT IGNORE INTO FACTURA (PACIENTE_ID_PACIENTE,FACTURA_NUMERO_COMPROBANTE,FACTURA_FECHA_EMISION,FACTURA_SUBTOTAL,FACTURA_IVA,FACTURA_TOTAL,FACTURA_ESTADO,FACTURA_MOTIVO_ANULACION) VALUES
(@p1,'TG23-FAC-01','2026-11-26 09:20:00',100,15,115,'EMITIDA',NULL),
(@p2,'TG23-FAC-02','2026-11-26 10:20:00',50,7.50,57.50,'EMITIDA',NULL),
(@p1,'TG23-FAC-03','2026-11-26 09:30:00',50,7.50,57.50,'ANULADA','Anulación de demostración');
INSERT INTO PAGO (FACTURA_ID_FACTURA,XEUSU_CODIGO,PAGO_FECHA_PAGO,PAGO_MONTO,PAGO_METODO_PAGO,PAGO_REFERENCIA,PAGO_ESTADO)
SELECT f.FACTURA_ID_FACTURA,@usuario,'2026-11-26 10:30:00',30,'EFECTIVO','TG23-PAG-01','REGISTRADO' FROM FACTURA f WHERE f.FACTURA_NUMERO_COMPROBANTE='TG23-FAC-01' AND NOT EXISTS(SELECT 1 FROM PAGO p WHERE p.FACTURA_ID_FACTURA=f.FACTURA_ID_FACTURA AND p.PAGO_REFERENCIA='TG23-PAG-01');
COMMIT;
